docutils.utils.smartquotes.educate_token:
def educate_tokens(text_tokens, attr=default_smartypants_attr, language='en'):
    """Return iterator that "educates" the items of `text_tokens`."""
    convert_quot = False
    do_dashes = False
    do_backticks = False
    do_quotes = False
    do_ellipses = False
    do_stupefy = False
    if attr == '1':
        do_quotes = True
        do_backticks = True
        do_dashes = 1
        do_ellipses = True
    elif attr == '2':
        do_quotes = True
        do_backticks = True
        do_dashes = 2
        do_ellipses = True
    elif attr == '3':
        do_quotes = True
        do_backticks = True
        do_dashes = 3
        do_ellipses = True
    elif attr == '-1':
        do_stupefy = True
    else:
        if 'q' in attr:
            do_quotes = True
        if 'b' in attr:
            do_backticks = True
        if 'B' in attr:
            do_backticks = 2
        if 'd' in attr:
            do_dashes = 1
        if 'D' in attr:
            do_dashes = 2
        if 'i' in attr:
            do_dashes = 3
        if 'e' in attr:
            do_ellipses = True
        if 'w' in attr:
            convert_quot = True
    prev_token_last_char = ' '
    for (ttype, text) in text_tokens:
        if (ttype == 'tag' or not text):
            yield text
            continue
        if ttype == 'literal':
            prev_token_last_char = text[-1:]
            yield text
            continue
        last_char = text[-1:]
        text = processEscapes(text)
        if convert_quot:
            text = text.replace('&quot;', '"')
        if do_dashes == 1:
            text = educateDashes(text)
        elif do_dashes == 2:
            text = educateDashesOldSchool(text)
        elif do_dashes == 3:
            text = educateDashesOldSchoolInverted(text)
        if do_ellipses:
            text = educateEllipses(text)
        if do_backticks:
            text = educateBackticks(text, language)
        if do_backticks == 2:
            text = educateSingleBackticks(text, language)
        if do_quotes:
            context = prev_token_last_char.replace('"', ';').replace("'", ';')
            text = educateQuotes(context + text, language)[1:]
        if do_stupefy:
            text = stupefyEntities(text, language)
        prev_token_last_char = last_char
        text = processEscapes(text, restore=True)
        yield text

docutils.frontend.validate_encoding_erro:
def validate_encoding_error_handler(setting: str, value: str | None = None, option_parser: OptionParser | None = None, config_parser: ConfigParser | None = None, config_section: str | None = None) -> str:
    if value is None:
        value = setting
    try:
        codecs.lookup_error(value)
    except LookupError:
        raise LookupError('unknown encoding error handler: "%s" (choices: "strict", "ignore", "replace", "backslashreplace", "xmlcharrefreplace", and possibly others; see documentation for the Python ``codecs`` module)' % value)
    return value

docutils.frontend.validate_encoding:
def validate_encoding(setting: str, value: str | None = None, option_parser: OptionParser | None = None, config_parser: ConfigParser | None = None, config_section: str | None = None) -> str | None:
    if value is None:
        value = setting
    if value == '':
        warnings.warn('Input encoding detection will be removed and the special encoding values None and "" become invalid in Docutils 1.0.', FutureWarning, stacklevel=2)
        return None
    try:
        codecs.lookup(value)
    except LookupError:
        prefix = (f'setting "{setting}":' if setting else '')
        raise LookupError(f'{prefix} unknown encoding: "{value}"')
    return value

docutils.frontend.validate_encoding_and_:
def validate_encoding_and_error_handler(setting: str, value: str | None = None, option_parser: OptionParser | None = None, config_parser: ConfigParser | None = None, config_section: str | None = None) -> str:
    """Check/normalize encoding settings

    Side-effect: if an error handler is included in the value, it is inserted
    into the appropriate place as if it were a separate setting/option.

    All arguments except `value` are ignored
    (kept for compatibility with "optparse" module).
    If there is only one positional argument, it is interpreted as `value`.
    """
    if ':' in value:
        (encoding, handler) = value.split(':')
        validate_encoding_error_handler(handler)
        if config_parser:
            config_parser.set(config_section, setting + '_error_handler', handler)
        else:
            setattr(option_parser.values, setting + '_error_handler', handler)
    else:
        encoding = value
    return validate_encoding(encoding)

docutils.parsers.rst.roles.rfc_reference:
def rfc_reference_role(role, rawtext, text, lineno, inliner, options=None, content=None):
    options = normalize_options(options)
    if '#' in text:
        (rfcnum, section) = nodes.unescape(text).split('#', 1)
    else:
        (rfcnum, section) = (nodes.unescape(text), None)
    try:
        rfcnum = int(rfcnum)
        if rfcnum < 1:
            raise ValueError
    except ValueError:
        msg = inliner.reporter.error('RFC number must be a number greater than or equal to 1; "%s" is invalid.' % text, line=lineno)
        prb = inliner.problematic(rawtext, rawtext, msg)
        return ([prb], [msg])
    ref = inliner.document.settings.rfc_base_url + inliner.rfc_url % rfcnum
    if section is not None:
        ref += '#' + section
    node = nodes.reference(rawtext, 'RFC ' + str(rfcnum), refuri=ref, **options)
    return ([node], [])

docutils.nodes.unescape:
def unescape(text: str, restore_backslashes: bool = False, respect_whitespace: bool = False) -> str:
    """
    Return a string with nulls removed or restored to backslashes.
    Backslash-escaped spaces are also removed.
    """
    if restore_backslashes:
        return text.replace('\x00', '\\')
    else:
        for sep in ['\x00 ', '\x00\n', '\x00']:
            text = ''.join(text.split(sep))
        return text

docutils.parsers.rst.roles.math_role:
def math_role(role, rawtext, text, lineno, inliner, options=None, content=None):
    options = normalize_options(options)
    text = nodes.unescape(text, True)
    node = nodes.math(rawtext, text, **options)
    return ([node], [])

docutils.parsers.rst.roles.code_role:
def code_role(role_name, rawtext, text, lineno, inliner, options=None, content=None):
    options = normalize_options(options)
    language = (role_name if role_name != 'code' else '')
    language = options.get('language', language)
    if language.lower() == 'none':
        language = ''
    classes = ['code']
    if 'classes' in options:
        classes.extend(options['classes'])
    if (language and language not in classes):
        classes.append(language)
    try:
        tokens = Lexer(nodes.unescape(text, True), language, inliner.document.settings.syntax_highlight)
    except LexerError as error:
        if 'language' in options:
            msg = inliner.reporter.warning(error)
            prb = inliner.problematic(rawtext, rawtext, msg)
            return ([prb], [msg])
        else:
            tokens = [('', nodes.unescape(text, True))]
    node = nodes.literal(rawtext, '', classes=classes)
    for (classes, value) in tokens:
        if classes:
            node += nodes.inline(value, value, classes=classes)
        else:
            node += nodes.Text(value)
    return ([node], [])
